import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema registration', () => {
  // specs/hal-engine-tool-input-validation/spec.md#6
  it('rejects an invalid static schema when registering the named tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Weather lookup',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

describe('ToolRegistry input validation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#4
  it('returns a required-property rejection without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const execute = async () => {
      executorCalls += 1;
      return 'sunny';
    };
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      execute
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: 0,
    });
  });
});

describe('ToolRegistry dynamic schema caching', () => {
  // specs/hal-engine-tool-input-validation/spec.md#8
  it('compiles each dynamic schema object only once', async () => {
    const registry = new ToolRegistry();
    const firstSchema = {type: 'object', properties: {location: {type: 'string'}}};
    const secondSchema = {type: 'object', properties: {location: {type: 'number'}}};
    let currentSchema = firstSchema;
    let executorCalls = 0;
    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: currentSchema}),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      await registry.execute('weather', {location: 'Berlin'});
      await registry.execute('weather', {location: 'Paris'});
      currentSchema = secondSchema;
      await registry.execute('weather', {location: 42});

      expect({compileCalls: compile.mock.calls.length, executorCalls}).toEqual({compileCalls: 2, executorCalls: 3});
    } finally {
      compile.mockRestore();
    }
  });
});

import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

const VALIDATOR_OPTIONS = {strict: false, validateFormats: false, coerceTypes: false, useDefaults: false};

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv(VALIDATOR_OPTIONS);
  private readonly validators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private compileSchema(definition: ToolDefinition): ValidateFunction {
    try {
      const validator = this.ajv.compile(definition.inputSchema);
      this.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${definition.name}`, {cause: error});
    }
  }

  private rejection(name: string, validator: ValidateFunction): ToolResponse {
    const error = validator.errors?.[0] as
      {keyword: string; instancePath?: string; dataPath?: string; params: Record<string, unknown>} | undefined;
    const path =
      error?.keyword === 'required'
        ? `${error.instancePath ?? error.dataPath ?? ''}/${String(error.params.missingProperty)}`
        : (error?.instancePath ?? error?.dataPath);
    const constraint = error?.keyword === 'type' ? `expected ${String(error.params.type)}` : error?.keyword;
    const result = `Invalid tool input at ${path || '/'}: ${constraint ?? 'schema constraint failed'}`;
    log.warn('tool', 'input rejected', {name, path, constraint});
    return {result};
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') this.compileSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for the tool input rejection contract. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validators.get(definition.inputSchema) ?? this.compileSchema(definition);
    if (!validator(input)) return this.rejection(name, validator);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

